import {
  GALAXY_FRAGMENT,
  GALAXY_VERTEX,
  MAX_COLORS,
  MAX_LAYERS,
} from './galaxy-shaders';
import type { GalaxyEngine, GalaxyProps, GalaxySettings } from './types';

const INTRO_SECONDS = 2.2;
const DEFAULT_FOCAL: [number, number] = [0.5, 0.5];
const DEFAULT_ROTATION: [number, number] = [1, 0];
const NO_COLORS: string[] = [];

interface LinkedProgram {
  program: WebGLProgram;
  uniforms: Map<string, WebGLUniformLocation | null>;
}

interface ProgramEntry {
  program: WebGLProgram | null;
  linked: LinkedProgram | null;
  done: boolean;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const pair = (
  value: [number, number] | undefined,
  fallback: [number, number],
): [number, number] =>
  Array.isArray(value) && value.length >= 2 ? value : fallback;

export function toGalaxySettings(props: GalaxyProps): GalaxySettings {
  const palette = Array.isArray(props.starColors)
    ? props.starColors.filter(Boolean).slice(0, MAX_COLORS)
    : NO_COLORS;
  return {
    focal: pair(props.focal, DEFAULT_FOCAL),
    rotation: pair(props.rotation, DEFAULT_ROTATION),
    starSpeed: props.starSpeed ?? 0.5,
    density: Math.max(0.01, props.density ?? 1),
    hueShift: props.hueShift ?? 140,
    disableAnimation: props.disableAnimation ?? false,
    speed: props.speed ?? 1,
    mouseInteraction: props.mouseInteraction ?? true,
    glowIntensity: Math.max(0, props.glowIntensity ?? 0.3),
    saturation: Math.max(0, props.saturation ?? 0),
    mouseRepulsion: props.mouseRepulsion ?? true,
    repulsionStrength: props.repulsionStrength ?? 2,
    twinkleIntensity: clamp(props.twinkleIntensity ?? 0.3, 0, 1),
    rotationSpeed: props.rotationSpeed ?? 0.1,
    autoCenterRepulsion: Math.max(0, props.autoCenterRepulsion ?? 0),
    transparent: props.transparent ?? true,
    lightMode: props.lightMode ?? false,
    palette,
    starSize: Math.max(0, props.starSize ?? 1),
    flareIntensity: Math.max(0, props.flareIntensity ?? 1),
    layers: clamp(Math.round(props.layers ?? 4), 2, MAX_LAYERS),
    reverse: props.direction === 'backward',
    clickWarp: props.clickWarp ?? true,
    intro: props.intro ?? true,
    backgroundColor: props.backgroundColor,
    opacity: clamp(props.opacity ?? 1, 0, 1),
    dpr: props.dpr,
  };
}

const variantKey = (palette: boolean, repel: boolean, warp: boolean) =>
  (palette ? 4 : 0) + (repel ? 2 : 0) + (warp ? 1 : 0);

function startProgram(
  gl: WebGL2RenderingContext,
  palette: boolean,
  repel: boolean,
  warp: boolean,
): WebGLProgram | null {
  const defines = `${palette ? '#define PALETTE\n' : ''}${repel ? '#define REPEL\n' : ''}${warp ? '#define WARP\n' : ''}`;
  const program = gl.createProgram();
  const vertex = gl.createShader(gl.VERTEX_SHADER);
  const fragment = gl.createShader(gl.FRAGMENT_SHADER);
  if (!program || !vertex || !fragment) return null;
  gl.shaderSource(vertex, GALAXY_VERTEX);
  gl.shaderSource(fragment, GALAXY_FRAGMENT.replace('\n', `\n${defines}`));
  gl.compileShader(vertex);
  gl.compileShader(fragment);
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, 'aPosition');
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  return program;
}

function finishProgram(
  gl: WebGL2RenderingContext,
  program: WebGLProgram,
): LinkedProgram | null {
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
  const uniforms = new Map<string, WebGLUniformLocation | null>();
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) {
      uniforms.set(
        info.name.replace('[0]', ''),
        gl.getUniformLocation(program, info.name),
      );
    }
  }
  return { program, uniforms };
}

export function createGalaxyEngine(
  canvas: HTMLCanvasElement,
  getSettings: () => GalaxySettings,
  isReduced: () => boolean,
  wake: () => void,
): GalaxyEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
  });
  if (!gl) return null;

  const parallel = gl.getExtension('KHR_parallel_shader_compile');
  const programs = new Map<number, ProgramEntry>();
  const entry = (palette: boolean, repel: boolean, warp: boolean) => {
    const key = variantKey(palette, repel, warp);
    let found = programs.get(key);
    if (!found) {
      found = {
        program: startProgram(gl, palette, repel, warp),
        linked: null,
        done: false,
      };
      programs.set(key, found);
    }
    return found;
  };
  const variant = (
    palette: boolean,
    repel: boolean,
    warp: boolean,
    wait: boolean,
  ) => {
    const found = entry(palette, repel, warp);
    if (!found.done && found.program) {
      if (
        !wait &&
        parallel &&
        !gl.getProgramParameter(found.program, parallel.COMPLETION_STATUS_KHR)
      ) {
        return null;
      }
      found.linked = finishProgram(gl, found.program);
      found.done = true;
    }
    return found.linked;
  };
  const deletePrograms = () => {
    programs.forEach((found) => {
      if (found.program) gl.deleteProgram(found.program);
    });
    programs.clear();
  };

  const initial = getSettings();
  const buffer = gl.createBuffer();
  const vao = gl.createVertexArray();
  if (
    !variant(initial.palette.length > 0, false, false, true) ||
    !buffer ||
    !vao
  ) {
    deletePrograms();
    gl.getExtension('WEBGL_lose_context')?.loseContext();
    return null;
  }

  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

  const probe = document
    .createElement('canvas')
    .getContext('2d', { willReadFrequently: true });
  const colorCache = new Map<string, number[]>();
  const parse = (value: string | undefined, fallback: number[]) => {
    if (!value) return fallback;
    const cached = colorCache.get(value);
    if (cached) return cached;
    let rgb = fallback;
    if (probe) {
      probe.clearRect(0, 0, 1, 1);
      probe.fillStyle = '#000000';
      probe.fillStyle = value;
      probe.fillRect(0, 0, 1, 1);
      const data = probe.getImageData(0, 0, 1, 1).data;
      rgb = [(data[0] ?? 0) / 255, (data[1] ?? 0) / 255, (data[2] ?? 0) / 255];
    }
    colorCache.set(value, rgb);
    return rgb;
  };
  const colors = new Float32Array(MAX_COLORS * 3);
  const WHITE = [1, 1, 1];
  const BLACK = [0, 0, 0];

  const view = { width: 1, height: 1 };
  const pointer = { x: 0.5, y: 0.5, inside: false };
  const state = {
    time: 0,
    gloss: 0,
    depth: 0,
    angle: 0,
    mx: 0.5,
    my: 0.5,
    active: 0,
    boost: 0,
    reveal: initial.intro && !isReduced() ? 0 : 1,
  };
  let last = 0;
  let visible = true;
  let lastDpr = initial.dpr;

  const render = () => {
    const s = getSettings();
    s.palette.forEach((value, index) =>
      colors.set(parse(value, WHITE), index * 3),
    );
    const mode = s.lightMode ? (s.transparent ? 3 : 2) : s.transparent ? 1 : 0;
    const background = parse(s.backgroundColor, s.lightMode ? WHITE : BLACK);
    const palette = s.palette.length > 0;
    const repel =
      s.autoCenterRepulsion > 0 ||
      (s.mouseRepulsion && s.repulsionStrength > 0 && state.active > 0);
    const warp = state.boost > 0;
    const base = variant(palette, false, false, true);
    if (!base) return;
    const program =
      (repel || warp ? variant(palette, repel, warp, false) : null) ?? base;
    const u = (name: string) => program.uniforms.get(name) ?? null;
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.useProgram(program.program);
    gl.bindVertexArray(vao);
    gl.uniform1f(u('uTime'), state.time);
    gl.uniform2f(u('uResolution'), canvas.width, canvas.height);
    gl.uniform2f(u('uFocal'), s.focal[0], s.focal[1]);
    gl.uniform2f(u('uRotation'), s.rotation[0], s.rotation[1]);
    gl.uniform1f(u('uGloss'), state.gloss);
    gl.uniform1f(u('uDepth'), state.depth);
    gl.uniform1f(u('uDensity'), s.density);
    gl.uniform1f(u('uHueShift'), s.hueShift);
    gl.uniform1f(u('uSpeed'), s.speed);
    gl.uniform2f(u('uMouse'), state.mx, state.my);
    const stretch = 1 + state.boost * 5;
    gl.uniform1f(
      u('uStarGlow'),
      (0.05 * s.glowIntensity * s.starSize) / Math.pow(stretch, 0.6),
    );
    gl.uniform1f(u('uFlareGain'), s.glowIntensity * s.flareIntensity);
    gl.uniform1f(u('uSquash'), 1 - 1 / (stretch * stretch));
    gl.uniform1f(u('uSaturation'), s.saturation);
    gl.uniform1f(u('uMouseRepulsion'), s.mouseRepulsion ? 1 : 0);
    gl.uniform1f(u('uTwinkleIntensity'), s.twinkleIntensity);
    gl.uniform1f(u('uRotationAngle'), state.angle);
    gl.uniform1f(u('uRepulsionStrength'), s.repulsionStrength);
    gl.uniform1f(u('uMouseActiveFactor'), state.active);
    gl.uniform1f(u('uAutoCenterRepulsion'), s.autoCenterRepulsion);
    gl.uniform1i(u('uLayers'), s.layers);
    gl.uniform3fv(u('uColors'), colors);
    gl.uniform1i(u('uColorCount'), s.palette.length);
    gl.uniform1f(u('uWarp'), state.boost);
    const fade = Math.min(1, state.reveal / 0.35);
    gl.uniform1f(u('uReveal'), fade * fade * (3 - 2 * fade));
    gl.uniform1f(u('uMode'), mode);
    gl.uniform3fv(u('uBackground'), background);
    gl.uniform1f(u('uOpacity'), s.opacity);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  };

  const frame = (now: number) => {
    if (!visible) return false;
    const s = getSettings();
    const reduce = isReduced();
    const dt = last ? clamp((now - last) / 1000, 0.0005, 0.05) : 1 / 60;
    last = now;
    const motion = s.disableAnimation || reduce ? 0 : 1;
    if (s.intro && !reduce && state.reveal < 1) {
      state.reveal = Math.min(1, state.reveal + dt / INTRO_SECONDS);
      state.boost = Math.max(state.boost, Math.pow(1 - state.reveal, 2) * 1.4);
    } else if (!s.intro || reduce) {
      state.reveal = 1;
    }
    const flight = (s.starSpeed / 10) * (s.reverse ? -1 : 1);
    state.time += dt * motion;
    state.gloss += dt * flight * motion;
    state.depth += dt * flight * s.speed * motion * (1 + state.boost * 14);
    state.angle += dt * s.rotationSpeed * motion;
    state.boost *= Math.exp(-dt * 1.3);
    if (state.boost < 0.001) state.boost = 0;

    const follow = 1 - Math.exp(-dt / 0.325);
    const engaged = s.mouseInteraction && pointer.inside && !reduce;
    if (engaged) {
      state.mx += (pointer.x - state.mx) * follow;
      state.my += (pointer.y - state.my) * follow;
    }
    const target = engaged ? 1 : 0;
    state.active += (target - state.active) * follow;
    if (Math.abs(target - state.active) < 0.001) state.active = target;

    render();
    const busy =
      motion > 0 ||
      state.boost > 0 ||
      state.active !== target ||
      state.reveal < 1;
    if (!busy) last = 0;
    return busy;
  };

  const resize = (width: number, height: number) => {
    const s = getSettings();
    view.width = Math.max(1, width);
    view.height = Math.max(1, height);
    const ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
    canvas.width = Math.max(1, Math.round(view.width * ratio));
    canvas.height = Math.max(1, Math.round(view.height * ratio));
    render();
    wake();
  };

  const locate = (x: number, y: number, inside: boolean) => {
    pointer.inside = inside;
    pointer.x = x / view.width;
    pointer.y = 1 - y / view.height;
  };

  const tinted = initial.palette.length > 0;
  const repelling =
    initial.autoCenterRepulsion > 0 ||
    (initial.mouseInteraction && initial.mouseRepulsion);
  if (initial.clickWarp || initial.intro) entry(tinted, false, true);
  if (repelling) entry(tinted, true, false);
  if (repelling && initial.clickWarp) entry(tinted, true, true);

  return {
    frame,
    update(idle) {
      const s = getSettings();
      if (s.dpr !== lastDpr) {
        lastDpr = s.dpr;
        resize(view.width, view.height);
        return;
      }
      if (idle) render();
      wake();
    },
    resize,
    setVisible(next) {
      visible = next;
      if (visible) {
        last = 0;
        wake();
      }
    },
    pointerMove(x, y, inside) {
      locate(x, y, inside);
      wake();
    },
    pointerDown(x, y, inside) {
      locate(x, y, inside);
      if (!pointer.inside || !getSettings().clickWarp || isReduced()) return;
      state.boost = Math.min(1.6, state.boost + 1);
      wake();
    },
    pointerUp(isMouse) {
      if (!isMouse) pointer.inside = false;
    },
    pointerLeave() {
      pointer.inside = false;
    },
    resetClock() {
      last = 0;
    },
    dispose() {
      deletePrograms();
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}

import type { GalaxyLook, GalaxyPalette, GalaxyPreset } from './types';

export const GALAXY_PALETTES: Record<GalaxyPalette, string[]> = {
  none: [],
  stardust: ['#ffffff', '#ffd9a3', '#a8c8ff'],
  ice: ['#ffffff', '#bfe3ff', '#8fb8ff'],
  gold: ['#fff6e0', '#ffd27a', '#ffb35c'],
  rose: ['#ffffff', '#ffc9d4', '#ffd9b8'],
};

const LOOK: GalaxyLook = {
  starColors: GALAXY_PALETTES.none,
  hueShift: 140,
  saturation: 0,
  density: 1,
  glowIntensity: 0.3,
  starSize: 1,
  flareIntensity: 1,
  twinkleIntensity: 0.3,
  starSpeed: 0.5,
  speed: 1,
  rotationSpeed: 0.1,
  layers: 4,
  direction: 'forward',
  mouseRepulsion: true,
  repulsionStrength: 2,
};

const PRESETS: Record<GalaxyPreset, GalaxyLook> = {
  classic: { ...LOOK },
  stardust: {
    ...LOOK,
    starColors: GALAXY_PALETTES.stardust,
    glowIntensity: 0.5,
    density: 1.4,
    twinkleIntensity: 0.6,
  },
  hyperdrive: {
    ...LOOK,
    starSpeed: 3,
    layers: 6,
    density: 1.2,
    glowIntensity: 0.4,
    mouseRepulsion: false,
  },
  sparkle: {
    ...LOOK,
    flareIntensity: 3,
    glowIntensity: 0.45,
    twinkleIntensity: 0.7,
    density: 0.8,
  },
  drift: {
    ...LOOK,
    direction: 'backward',
    starSpeed: 0.3,
    rotationSpeed: 0.03,
    glowIntensity: 0.35,
  },
  cluster: {
    ...LOOK,
    starColors: GALAXY_PALETTES.gold,
    glowIntensity: 0.5,
    density: 1.6,
    twinkleIntensity: 0.4,
  },
};

/** The look of one of the demo presets. */
export function galaxyPreset(name: GalaxyPreset): GalaxyLook {
  const look = PRESETS[name];
  return { ...look, starColors: [...look.starColors] };
}

function isGalaxyPalette(value: unknown): value is GalaxyPalette {
  return typeof value === 'string' && value in GALAXY_PALETTES;
}

/** The name of the palette matching a list of star colors, or 'none'. */
export function galaxyPaletteName(colors: string[]): GalaxyPalette {
  const key = colors.join(',');
  const names = Object.keys(GALAXY_PALETTES).filter(isGalaxyPalette);
  return (
    names.find((name) => GALAXY_PALETTES[name].join(',') === key) ?? 'none'
  );
}

export function isGalaxyPreset(value: unknown): value is GalaxyPreset {
  return typeof value === 'string' && value in PRESETS;
}

export const MAX_LAYERS = 8;
export const MAX_COLORS = 4;

export const GALAXY_VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

/** Variants are compiled by inserting PALETTE / REPEL / WARP defines after the version line. */
export const GALAXY_FRAGMENT = `#version 300 es
precision highp float;
precision highp int;
uniform float uTime;
uniform vec2 uResolution;
uniform vec2 uFocal;
uniform vec2 uRotation;
uniform float uGloss;
uniform float uDepth;
uniform float uDensity;
uniform float uHueShift;
uniform float uSpeed;
uniform vec2 uMouse;
uniform float uStarGlow;
uniform float uFlareGain;
uniform float uSquash;
uniform float uSaturation;
uniform float uMouseRepulsion;
uniform float uTwinkleIntensity;
uniform float uRotationAngle;
uniform float uRepulsionStrength;
uniform float uMouseActiveFactor;
uniform float uAutoCenterRepulsion;
uniform int uLayers;
uniform vec3 uColors[4];
uniform int uColorCount;
uniform float uWarp;
uniform float uReveal;
uniform float uMode;
uniform vec3 uBackground;
uniform float uOpacity;
out vec4 outColor;

#define STAR_COLOR_CUTOFF 0.2
#define MAT45 mat2(0.7071, -0.7071, 0.7071, 0.7071)
#define PERIOD 3.0

float Hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float tri(float x) {
  return abs(fract(x) * 2.0 - 1.0);
}

float tris(float x) {
  float t = fract(x);
  return 1.0 - smoothstep(0.0, 1.0, abs(2.0 * t - 1.0));
}

float trisn(float x) {
  float t = fract(x);
  return 2.0 * (1.0 - smoothstep(0.0, 1.0, abs(2.0 * t - 1.0))) - 1.0;
}

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

float Star(vec2 uv, float flare, vec2 radial, float invReach) {
#ifdef WARP
  float along = dot(uv, radial);
  float d = sqrt(max(dot(uv, uv) - uSquash * along * along, 0.0));
#else
  float d = length(uv);
#endif
  float m = uStarGlow / d;
  float rays = smoothstep(0.0, 1.0, 1.0 - abs(uv.x * uv.y * 1000.0));
  m += rays * flare * uFlareGain;
  uv *= MAT45;
  rays = smoothstep(0.0, 1.0, 1.0 - abs(uv.x * uv.y * 1000.0));
  m += rays * 0.3 * flare * uFlareGain;
  m *= smoothstep(1.0, 0.2, d * invReach);
#ifdef WARP
  m *= mix(1.0, smoothstep(1.0, 0.55, length(uv) * invReach), min(uWarp * 4.0, 1.0));
#endif
  return m;
}

vec3 StarLayer(vec2 uv, vec2 radial, vec2 repelAt, float pushCells, float spread) {
  vec3 col = vec3(0.0);
  vec2 gv = fract(uv) - 0.5;
  vec2 id = floor(uv);
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      vec2 offset = vec2(float(x), float(y));
      vec2 si = id + offset;
      float seed = Hash21(si);
      float size = fract(seed * 345.32);
      float glossLocal = tri(uGloss / (PERIOD * seed + 1.0));
      float flareSize = smoothstep(0.9, 1.0, size) * glossLocal;

#ifdef PALETTE
      float pick = Hash21(si + 7.0) * float(uColorCount);
      vec3 base = uColors[int(min(floor(pick), float(uColorCount - 1)))];
#else
      float red = smoothstep(STAR_COLOR_CUTOFF, 1.0, Hash21(si + 1.0)) + STAR_COLOR_CUTOFF;
      float blu = smoothstep(STAR_COLOR_CUTOFF, 1.0, Hash21(si + 3.0)) + STAR_COLOR_CUTOFF;
      float grn = min(red, blu) * seed;
      vec3 base = vec3(red, grn, blu);
      float hue = atan(base.g - base.r, base.b - base.r) / (2.0 * 3.14159) + 0.5;
      hue = fract(hue + uHueShift / 360.0);
      float sat = length(base - vec3(dot(base, vec3(0.299, 0.587, 0.114)))) * uSaturation;
      float val = max(max(base.r, base.g), base.b);
      base = hsv2rgb(vec3(hue, sat, val));
#endif

      vec2 pad = vec2(tris(seed * 34.0 + uTime * uSpeed / 10.0), tris(seed * 38.0 + uTime * uSpeed / 30.0)) - 0.5;
      vec2 shift = vec2(0.0);
      float invReach = 1.0;
#ifdef REPEL
      vec2 away = si + 0.5 + pad - repelAt;
      float dist = length(away);
      float q = dist * spread;
      float cells = pushCells * exp(-q * q);
      float moved = cells * inversesqrt(1.0 + cells * cells * 2.78);
      shift = away * (moved / max(dist, 0.0001));
      invReach = 1.0 / (1.0 - moved);
#endif
      float star = Star(gv - offset - pad - shift, flareSize, radial, invReach);
      float twinkle = trisn(uTime * uSpeed + seed * 6.2831) * 0.5 + 1.0;
      twinkle = mix(1.0, twinkle, uTwinkleIntensity);
      col += star * twinkle * size * base;
    }
  }
  return col;
}

void main() {
  vec2 focalPx = uFocal * uResolution;
  vec2 uv = (gl_FragCoord.xy - focalPx) / uResolution.y;
  vec2 mouseNorm = uMouse - vec2(0.5);

  vec2 repelAt = vec2(0.0);
  float strength = 0.0;
  float push = 0.0;
  if (uAutoCenterRepulsion > 0.0) {
    strength = uAutoCenterRepulsion;
    push = strength * 0.05;
  } else if (uMouseRepulsion > 0.5) {
    repelAt = (uMouse * uResolution - focalPx) / uResolution.y;
    strength = max(uRepulsionStrength, 0.0);
    push = strength * 0.05 * uMouseActiveFactor;
  } else {
    uv += mouseNorm * 0.1 * uMouseActiveFactor;
  }
  float radius = 0.16 + 0.04 * strength;

  vec2 radial = length(uv) > 0.0001 ? normalize(uv) : vec2(1.0, 0.0);
  float angle = uRotationAngle;
  uv = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * uv;
  uv = mat2(uRotation.x, -uRotation.y, uRotation.y, uRotation.x) * uv;
  radial = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * radial;
  radial = mat2(uRotation.x, -uRotation.y, uRotation.y, uRotation.x) * radial;
  repelAt = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * repelAt;
  repelAt = mat2(uRotation.x, -uRotation.y, uRotation.y, uRotation.x) * repelAt;

  vec3 col = vec3(0.0);
  float layers = float(uLayers);
  for (int k = 0; k < 8; k++) {
    if (k >= uLayers) break;
    float i = float(k) / layers;
    float depth = fract(i + uDepth);
    float scale = mix(20.0 * uDensity, 0.5 * uDensity, depth);
    float fade = depth * smoothstep(1.0, 0.9, depth);
    vec2 offset = vec2(i * 453.32);
    col += StarLayer(uv * scale + offset, radial, repelAt * scale + offset, push * scale, 1.0 / (scale * radius)) * fade;
  }
  col *= uReveal;

  if (uMode > 1.5) {
    vec3 lit = col * smoothstep(0.0, 0.3, length(col));
    float energy = max(max(lit.r, lit.g), lit.b);
    vec3 tint = lit / max(energy, 0.0001);
    vec3 ink = tint * (0.16 / max(dot(tint, vec3(0.2126, 0.7152, 0.0722)), 0.16));
    float coverage = pow(min(energy * 1.3, 1.0), 1.3) * 0.92 * uOpacity;
    outColor = uMode > 2.5 ? vec4(ink * coverage, coverage) : vec4(mix(uBackground, ink, coverage), 1.0);
  } else if (uMode > 0.5) {
    float alpha = min(smoothstep(0.0, 0.3, length(col)), 1.0) * uOpacity;
    outColor = vec4(col * alpha, alpha);
  } else {
    outColor = vec4(mix(uBackground, col, uOpacity), 1.0);
  }
}`;

export { default as Galaxy } from './Galaxy.vue';
export {
  GALAXY_PALETTES,
  galaxyPaletteName,
  galaxyPreset,
  isGalaxyPreset,
} from './galaxy-presets';
export type {
  GalaxyDirection,
  GalaxyLook,
  GalaxyPalette,
  GalaxyPreset,
  GalaxyProps,
} from './types';

export type GalaxyDirection = 'forward' | 'backward';
export type GalaxyPalette = 'none' | 'stardust' | 'ice' | 'gold' | 'rose';
export type GalaxyPreset =
  | 'classic'
  | 'stardust'
  | 'hyperdrive'
  | 'sparkle'
  | 'drift'
  | 'cluster';

export interface GalaxyProps {
  /** Center of the starfield, from 0 to 1. */
  focal?: [number, number];
  /** Fixed rotation of the starfield as a [cos, sin] pair. */
  rotation?: [number, number];
  /** How fast you travel through the stars. */
  starSpeed?: number;
  /** How densely the stars are packed. */
  density?: number;
  /** Shifts the hue of the stars, in degrees. */
  hueShift?: number;
  /** Freezes the animation. */
  disableAnimation?: boolean;
  /** Overall speed of the animation. */
  speed?: number;
  /** Lets the cursor interact with the stars. */
  mouseInteraction?: boolean;
  /** Brightness of the glow around each star. */
  glowIntensity?: number;
  /** Color saturation of the stars, from 0 to 1. */
  saturation?: number;
  /** Pushes the stars away from the cursor. When off, the field shifts with the cursor instead. */
  mouseRepulsion?: boolean;
  /** Strength of the push away from the cursor. */
  repulsionStrength?: number;
  /** How much the stars twinkle, from 0 to 1. */
  twinkleIntensity?: number;
  /** How fast the starfield rotates. */
  rotationSpeed?: number;
  /** Pushes the stars away from the center without the cursor. 0 turns it off. */
  autoCenterRepulsion?: number;
  /** Shows the page behind the stars. When off, the stars sit on the background color. */
  transparent?: boolean;
  /** Draws the stars as ink for light backgrounds. */
  lightMode?: boolean;
  /** Up to four colors the stars are picked from. Replaces the hue shift and saturation coloring. */
  starColors?: string[];
  /** Size of each star glow. */
  starSize?: number;
  /** Strength of the cross flares on the brightest stars. */
  flareIntensity?: number;
  /** Number of star layers, from 2 to 8. */
  layers?: number;
  /** Whether you fly into the stars or drift back out of them. */
  direction?: GalaxyDirection;
  /** Clicking jumps forward at warp speed. */
  clickWarp?: boolean;
  /** Drops out of warp speed on mount. */
  intro?: boolean;
  /** Background behind the stars when transparent is off, or the paper color in light mode. */
  backgroundColor?: string;
  /** Opacity of the whole effect. */
  opacity?: number;
  /** Maximum device pixel ratio, capped at 2. */
  dpr?: number;
  class?: string;
}

/** The tunable look shared by the demo presets. */
export interface GalaxyLook {
  starColors: string[];
  hueShift: number;
  saturation: number;
  density: number;
  glowIntensity: number;
  starSize: number;
  flareIntensity: number;
  twinkleIntensity: number;
  starSpeed: number;
  speed: number;
  rotationSpeed: number;
  layers: number;
  direction: GalaxyDirection;
  mouseRepulsion: boolean;
  repulsionStrength: number;
}

export interface GalaxyDemoParams extends Omit<GalaxyLook, 'starColors'> {
  preset: GalaxyPreset;
  palette: GalaxyPalette;
  mouseInteraction: boolean;
  clickWarp: boolean;
  intro: boolean;
  lightMode: boolean;
}

export interface GalaxySettings {
  focal: [number, number];
  rotation: [number, number];
  starSpeed: number;
  density: number;
  hueShift: number;
  disableAnimation: boolean;
  speed: number;
  mouseInteraction: boolean;
  glowIntensity: number;
  saturation: number;
  mouseRepulsion: boolean;
  repulsionStrength: number;
  twinkleIntensity: number;
  rotationSpeed: number;
  autoCenterRepulsion: number;
  transparent: boolean;
  lightMode: boolean;
  palette: string[];
  starSize: number;
  flareIntensity: number;
  layers: number;
  reverse: boolean;
  clickWarp: boolean;
  intro: boolean;
  backgroundColor?: string;
  opacity: number;
  dpr?: number;
}

export interface GalaxyEngine {
  /** Advances one frame. Returns false when the loop should stop. */
  frame: (now: number) => boolean;
  /** Applies new settings: resizes on a pixel-ratio change, otherwise redraws when the loop is idle. */
  update: (idle: boolean) => void;
  resize: (width: number, height: number) => void;
  setVisible: (visible: boolean) => void;
  /** Pointer position relative to the container, in CSS px from the top-left. */
  pointerMove: (x: number, y: number, inside: boolean) => void;
  pointerDown: (x: number, y: number, inside: boolean) => void;
  pointerUp: (isMouse: boolean) => void;
  pointerLeave: () => void;
  resetClock: () => void;
  dispose: () => void;
}
